        for part, exp_len in zip(parts, expected_lengths):
            if len(part) != exp_len:
                raise ValueError('ISBN groups have unexpected length')
        # Validate characters
        for i, part in enumerate(parts):
            if i == 3:  # checksum part
                if part not in '0123456789X':
                    raise ValueError('Invalid checksum character')
            else:
                if not part.isdigit():
                    raise ValueError('ISBN must contain digits only in non-checksum groups')
        # Remove hyphens to check digits
